# First, let's look at the CONTEXT structure and search for key sections
print("CONTEXT size:", await CONTEXT.info())
print("---")

# Search for the grade, facts, first wrong step, etc.
for term in ["[grade]", "[grader tail]", "[facts]", "[first wrong step]", "[checkpoint", "STATUS.json", "verifier", "grading", "c_m15", "c_m29"]:
    results = await CONTEXT.search(term)
    if results:
        print(f"\n'{term}' found at offsets:", [(r["offset"], r.get("snippet","")[:100]) for r in results])
    else:
        print(f"'{term}' not found")
